package com.aoo.bcg.common.lifecycle;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Named executor boundary propagating immutable context, reporting task failures and draining on shutdown. */
public final class ManagedAsyncExecutor implements AutoCloseable{private final ExecutorService executor;private final Duration grace;private final Consumer<Throwable>failureSink;private static final ThreadLocal<Map<String,String>>CONTEXT=ThreadLocal.withInitial(Map::of);public ManagedAsyncExecutor(ExecutorService executor,Duration grace,Consumer<Throwable>failureSink){this.executor=Objects.requireNonNull(executor);this.grace=Objects.requireNonNull(grace);this.failureSink=Objects.requireNonNull(failureSink);if(grace.isNegative()||grace.isZero())throw new IllegalArgumentException("positive shutdown grace required");}public Future<?>submit(Map<String,String>context,Runnable task){Map<String,String>captured=Map.copyOf(context);return executor.submit(()->{Map<String,String>previous=CONTEXT.get();CONTEXT.set(captured);try{task.run();}catch(Throwable failure){failureSink.accept(failure);throw failure;}finally{if(previous.isEmpty())CONTEXT.remove();else CONTEXT.set(previous);}});}public static Map<String,String>currentContext(){return CONTEXT.get();}@Override public void close(){executor.shutdown();try{if(!executor.awaitTermination(grace.toMillis(),TimeUnit.MILLISECONDS))executor.shutdownNow();}catch(InterruptedException interrupted){executor.shutdownNow();Thread.currentThread().interrupt();}}}
